"use client";
import type { RefObject } from "react";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisNavbarContent } from "./components/navbar/content";
import View5 from "./components/navbar/variants/06-simple";
export type { ArtemisNavbarColumn, ArtemisNavbarContent, ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "./components/navbar/content";
export interface ArtemisNavbarProps { className?: string; scrollContainer?: RefObject<HTMLElement | null>; variant?: "simple"; /** The words on the navbar; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisNavbarContent>; }
export function ArtemisNavbar({ className, scrollContainer, content }: ArtemisNavbarProps) {return <ArtemisScope className={`art:sticky art:top-0 art:z-50 ${className ?? ""}`}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View5 scrollContainer={scrollContainer} content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisNavbarLink {
  label: string;
  href: string;
}

/** A link inside an open menu. */
export interface ArtemisNavbarMenuLink extends ArtemisNavbarLink {
  /** A short line under the label. morph and feature-morph. */
  description?: string;
  /** The card's icon. feature-morph, which keeps its own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** A small heading over a list of links, inside an open menu. */
export interface ArtemisNavbarColumn {
  title: string;
  links: ArtemisNavbarLink[];
}

/** A top-level item that opens a menu. */
export interface ArtemisNavbarMenu {
  label: string;
  /** Headed columns of links. pill-groups and mega-menu; morph and feature-morph list their links. */
  columns?: ArtemisNavbarColumn[];
  /** Links, each with an optional description and icon. morph and feature-morph; pill-groups and mega-menu show them as one column when `columns` is left out. feature-morph sets them in a fixed two-by-two panel, so four fill it. */
  links?: ArtemisNavbarMenuLink[];
  /** A highlighted card beside the columns. mega-menu. */
  feature?: { title: string; description: string; href: string };
}

/** The words on an Artemis navbar. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisNavbarContent {
  /** The name beside the logo mark, and where it links. All layouts. */
  brand: ArtemisNavbarLink;
  /** Items that open a menu, shown before `links`. pill-groups, mega-menu, morph and feature-morph. */
  menus?: ArtemisNavbarMenu[];
  /** Plain links in the bar. All layouts. The bars of morph and feature-morph have a fixed width: their own two one-word menus and two links fill them, and more or longer labels wrap or overflow. */
  links: ArtemisNavbarLink[];
  /** The quiet sign-in link. pill-groups, mega-menu, morph and feature-morph. */
  login?: ArtemisNavbarLink;
  /** A sign-up link beside sign-in. pill-groups. */
  signup?: ArtemisNavbarLink;
  /** The main button. All layouts. */
  cta: ArtemisNavbarLink;
  /** A line at the foot of an open menu, beside a link to `cta`. pill-groups and mega-menu. */
  menuNote?: string;
}

"use client";
// @zeus-internal
import { artemisEscapeDismiss } from "../../../lib/escape-dismiss";
import { useState, type RefObject } from "react";
import { AnimatePresence, motion, useMotionValueEvent, useReducedMotion, useScroll } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisNavbarContent } from "../content";
const DEFAULT = {
    brand: { label: "Artemis", href: "/" },
    links: [{ label: "Product", href: "#product" }, { label: "Solutions", href: "#solutions" }, { label: "Resources", href: "#resources" }, { label: "Pricing", href: "#pricing" }],
    cta: { label: "Get started", href: "#" },
} satisfies ArtemisNavbarContent;
export default function NavbarSimple({ scrollContainer, content }: { scrollContainer?: RefObject<HTMLElement | null>; content?: Partial<ArtemisNavbarContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const reduced = !!useReducedMotion();

    const { scrollY } = useScroll(scrollContainer ? { container: scrollContainer } : {});
    const [scrolled, setScrolled] = useState(false);
    useMotionValueEvent(scrollY, "change", value => setScrolled(value > 8));
    const [selected, setSelected] = useState(0);
    const [mobile, setMobile] = useState(false);
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    const transition = { duration: reduced ? 0 : 0.2, ease: ARTEMIS_EASE_OUT };
    return <header onKeyDown={event => artemisEscapeDismiss(event, () => setMobile(false))} className={`art:pointer-events-none art:sticky art:top-0 art:z-50 art:w-full art:transition-[background-color,border-color,backdrop-filter] art:duration-300 ${scrolled || mobile ? "art:border-border/55 art:border-b art:bg-background/78 art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/72" : "art:border-transparent art:border-b art:bg-transparent"}`}>
          <nav aria-label="Primary" className="art:pointer-events-auto art:mx-auto art:flex art:h-14 art:w-full art:max-w-7xl art:items-center art:justify-between art:gap-5 art:px-4 art:@min-[640px]/artemis:px-6">
            <div className="art:flex art:min-w-0 art:items-center art:gap-7">
              <a href={copy.brand.href} className="art:flex art:min-w-0 art:shrink-0 art:items-center art:gap-2.5 art:rounded-md art:font-semibold art:text-foreground art:text-sm art:tracking-tight art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/25">
                <span className="art:grid art:size-7 art:shrink-0 art:place-items-center art:bg-foreground art:text-background art:rounded-full">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-hexagon art:size-4" aria-hidden="true">
                    <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>
                  </svg>
                </span>
                <span className="art:truncate">
                  {copy.brand.label}
                </span>
              </a>
              <div className="art:hidden art:items-center art:@min-[768px]/artemis:flex">
                {copy.links.map((link, index) => <a key={link.label} href={link.href} aria-current={selected === index ? "page" : undefined} className={`art:flex art:min-h-10 art:items-center art:rounded-md art:px-3 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:bg-muted ${selected === index ? "art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} onClick={() => setSelected(index)}>{link.label}</a>)}
              </div>
            </div>
            <div className="art:flex art:shrink-0 art:items-center art:gap-1.5">
              <motion.a {...press} className="art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:hidden art:@min-[640px]/artemis:inline-flex art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                {copy.cta.label}
              </motion.a>
              <motion.button {...press} onClick={() => setMobile(!mobile)} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:grid art:size-10 art:place-items-center art:text-foreground art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/25 art:@min-[768px]/artemis:hidden art:rounded-full" aria-label={mobile ? "Close menu" : "Open menu"} aria-expanded={mobile} tabIndex={0}>
                <span className="art:relative art:block art:h-3.5 art:w-4.5">
                  <motion.span className="art:absolute art:top-0 art:left-0 art:h-px art:w-full art:bg-current" animate={{ y: mobile ? 6 : 0, rotate: mobile ? 45 : 0 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL}/>
                  <motion.span className="art:absolute art:top-1.5 art:left-0 art:h-px art:w-full art:bg-current" animate={{ opacity: mobile ? 0 : 1, scaleX: mobile ? 0.5 : 1 }} transition={transition}/>
                  <motion.span className="art:absolute art:bottom-0 art:left-0 art:h-px art:w-full art:bg-current" animate={{ y: mobile ? -6 : 0, rotate: mobile ? -45 : 0 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL}/>
                </span>
              </motion.button>
            </div>
          </nav>
          <AnimatePresence>{mobile && <motion.div className="art:pointer-events-auto art:absolute art:inset-x-0 art:top-full art:border-border/55 art:border-b art:bg-background/96 art:px-4 art:py-3 art:backdrop-blur-xl art:@min-[768px]/artemis:hidden" initial={reduced ? { opacity: 0 } : { opacity: 0, y: -8 }} animate={reduced ? { opacity: 1 } : { opacity: 1, y: 0 }} exit={reduced ? { opacity: 0 } : { opacity: 0, y: -6 }} transition={transition}>
            <div className="art:mx-auto art:grid art:max-w-7xl art:gap-1">
              {copy.links.map((link, index) => <motion.a key={link.label} href={link.href} aria-current={selected === index ? "page" : undefined} className={`art:flex art:min-h-11 art:items-center art:rounded-lg art:px-3 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:bg-muted ${selected === index ? "art:bg-muted art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/60 art:hover:text-foreground"}`} initial={reduced ? false : { opacity: 0, y: -4 }} animate={reduced ? { opacity: 1 } : { opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.18, delay: reduced ? 0 : index * 0.025, ease: ARTEMIS_EASE_OUT }} onClick={() => { setSelected(index); setMobile(false); }}>{link.label}</motion.a>)}
              <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-2 art:w-full art:@min-[640px]/artemis:hidden art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>{copy.cta.label}</motion.a>
            </div>
          </motion.div>}</AnimatePresence>
        </header>;
}

// @zeus-internal
import type { KeyboardEvent } from "react";
export function artemisEscapeDismiss(event: KeyboardEvent<HTMLElement>, close: () => void) {
  if (event.key !== "Escape" || event.defaultPrevented) return;
  const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[aria-expanded="true"]')];
  if (!triggers.length) return;
  const trigger = triggers.find(button => button.getClientRects().length > 0) ?? triggers[0];
  event.preventDefault();
  event.stopPropagation();
  close();
  trigger?.focus();
}
